import{_ as t,o as r,c as o,ah as a}from"./chunks/framework.CRsDMGp2.js";const m=JSON.parse('{"title":"Guide — Chef de projet & Collaborateurs","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/chef-projet-collaborateurs.md","filePath":"src/guide/chef-projet-collaborateurs.md"}'),n={name:"guide/chef-projet-collaborateurs.md"};function i(s,e,l,u,p,d){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="guide-—-chef-de-projet-collaborateurs" tabindex="-1">Guide — Chef de projet &amp; Collaborateurs <a class="header-anchor" href="#guide-—-chef-de-projet-collaborateurs" aria-label="Permalink to &quot;Guide — Chef de projet &amp; Collaborateurs&quot;">​</a></h1><p>Piloter et exécuter les projets au quotidien.</p><p>Ce guide couvre deux profils proches : le <strong>Chef de projet</strong>, qui pilote un projet de bout en bout, et les <strong>Collaborateurs / Consultants</strong> (7 métiers), qui exécutent les missions techniques qui leur sont confiées.</p><h2 id="partie-a-—-chef-de-projet" tabindex="-1">Partie A — Chef de projet <a class="header-anchor" href="#partie-a-—-chef-de-projet" aria-label="Permalink to &quot;Partie A — Chef de projet&quot;">​</a></h2><h3 id="creer-et-piloter-un-projet" tabindex="-1">Créer et piloter un projet <a class="header-anchor" href="#creer-et-piloter-un-projet" aria-label="Permalink to &quot;Créer et piloter un projet&quot;">​</a></h3><ul><li>Créez un nouveau projet depuis <strong>Projets &gt; Nouveau projet</strong> : client, chef de projet, apporteur d&#39;affaires éventuel et <strong>type de projet</strong>. Le type choisi pré-remplit automatiquement les phases et jalons par défaut de la méthodologie correspondante (huit types disponibles : Site web / présence digitale, Application ou plateforme sur mesure, Conseil en transformation numérique, Architecture des systèmes d&#39;information, Cloud &amp; Infrastructures, Cybersécurité, Intelligence artificielle &amp; données, Formation).</li><li>Ajustez les phases et jalons pré-remplis si besoin (renommage, réordonnancement, pourcentage de facturation de chaque jalon facturable) depuis l&#39;onglet <strong>Suivi</strong> de la fiche projet.</li><li>Chaque projet porte une référence unique (ex. <code>NAIA-0142</code>), utilisée par les pôles pour le désigner.</li><li>Constituez l&#39;équipe projet depuis l&#39;onglet <strong>Équipe</strong> et affectez les tâches, y compris à des partenaires externes — précisez leur mode de rémunération (forfait, pourcentage de jalon ou taux journalier).</li><li>Besoin d&#39;un renfort ? Dans l&#39;onglet <strong>Équipe</strong>, <strong>Demander un renfort</strong> : décrivez le profil requis (ex. « Dev Vue senior ») et ajoutez des précisions si besoin. La demande part au pôle RH ; la personne qu&#39;il retient rejoint automatiquement l&#39;équipe, et vous en êtes notifié.</li><li>Les pôles Support et Commercial peuvent signaler un besoin de développement sur votre projet : il devient une tâche, avec un badge <strong>Support</strong> ou <strong>Commercial</strong> qui en indique l&#39;origine, et vous êtes notifié.</li><li>Suivez l&#39;avancement global via les vues <strong>Gantt</strong> (par phase et jalon) ou <strong>Kanban</strong> (par statut de tâche).</li></ul><h3 id="jalons-et-facturation" tabindex="-1">Jalons et facturation <a class="header-anchor" href="#jalons-et-facturation" aria-label="Permalink to &quot;Jalons et facturation&quot;">​</a></h3><ul><li>À la validation d&#39;un jalon <strong>non facturable</strong>, ajoutez un compte-rendu visible par le client (et, quand c&#39;est pertinent, un lien de démo vers une version fonctionnelle du projet à cette étape).</li><li>La validation d&#39;un jalon <strong>facturable</strong> enregistre le montant dû, calculé sur son pourcentage de facturation, et le signale automatiquement au pôle Facturation.</li><li>Une facture interne en retard vous est signalée à titre informatif. Seul un retard de paiement signalé par le pôle Facturation peut mener au blocage du projet, sur décision de la Direction ou de l&#39;administrateur — vous ne pouvez ni bloquer ni débloquer un projet.</li><li>Sur un projet <strong>bloqué pour impayé</strong>, les tâches déjà démarrées peuvent se terminer, mais vous ne pouvez ni démarrer de nouvelle tâche ni valider de jalon avant le déblocage. Vous pouvez toujours planifier des tâches, échanger et déposer des documents.</li></ul><h3 id="avenants-et-cloture" tabindex="-1">Avenants et clôture <a class="header-anchor" href="#avenants-et-cloture" aria-label="Permalink to &quot;Avenants et clôture&quot;">​</a></h3><ul><li>Initiez une demande d&#39;avenant depuis l&#39;onglet <strong>Avenants</strong> si le périmètre, le délai ou le budget du projet doit évoluer. L&#39;administrateur formalise ensuite le document, qui part en signature électronique auprès du client ; l&#39;impact budgétaire ne s&#39;applique qu&#39;une fois l&#39;avenant signé.</li><li>À la clôture du projet, cochez l&#39;éventuelle éligibilité <strong>NextBoxx</strong> et ajoutez une note libre si le projet peut servir de cas réel pour les formations internes.</li></ul><h2 id="partie-b-—-collaborateurs-consultants" tabindex="-1">Partie B — Collaborateurs / Consultants <a class="header-anchor" href="#partie-b-—-collaborateurs-consultants" aria-label="Permalink to &quot;Partie B — Collaborateurs / Consultants&quot;">​</a></h2><p>Le tronc commun du parcours est identique quel que soit votre métier (Consultant en transformation numérique, Développeur, Architecte SI, Expert Cloud &amp; Infrastructures, Expert Cybersécurité, Expert IA &amp; Données, Formateur interne) — seul le livrable attendu change.</p><h3 id="vos-missions" tabindex="-1">Vos missions <a class="header-anchor" href="#vos-missions" aria-label="Permalink to &quot;Vos missions&quot;">​</a></h3><ul><li>Consultez les tâches qui vous sont assignées, tous projets confondus, depuis votre tableau de bord ou l&#39;onglet <strong>Tâches</strong> d&#39;un projet.</li><li>Mettez à jour leur avancement (à faire, en cours, terminée) et déposez vos livrables directement depuis leur fiche.</li><li>Échangez avec le chef de projet et, selon le contexte, le client via la messagerie intégrée du projet.</li></ul>',14)])])}const h=t(n,[["render",i]]);export{m as __pageData,h as default};
